                  <span class="preset-label">第一卷经典切入模板：</span>
                  <div class="preset-chips">
                    <button type="button" class="preset-chip" onclick="RakudaiOpening.applySceneTemplate('training')">第三训练场·初入切磋</button>
                    <button type="button" class="preset-chip" onclick="RakudaiOpening.applySceneTemplate('dorm')">第一宿舍·清晨报道</button>
                    <button type="button" class="preset-chip" onclick="RakudaiOpening.applySceneTemplate('director')">理事长室·交涉面谈</button>
                    <button type="button" class="preset-chip" onclick="RakudaiOpening.applySceneTemplate('ceremony')">开学典礼·选拔改制</button>
                  </div>
                </div>
                <div class="form-grid-2">
                  <div class="form-field">
                    <label class="field-label" for="opening-chapter">章段（第一卷）</label>
