        }

        var greeting = greetingMatch ? greetingMatch[1].trim() : "";
        if (!greeting && !chapterMatch && !timeMatch && !locationMatch) {
          greeting = text.trim();
        }

        return {
          chapter: chapter,
          time: timeMatch ? timeMatch[1].trim() : "",
          location: locationMatch ? locationMatch[1].trim() : "",
          greeting: greeting
        };
