      // ================= 核心：100% 像素级复原的 SVG 雷达图引擎 =================
      function renderRadarEngine(svgId, grades) {
        var svg = document.getElementById(svgId);
        if (!svg) return;

        while (svg.firstChild) {
          svg.removeChild(svg.firstChild);
        }

        var cx = 190,
          cy = 185;
        var R_outer = 115;
        var gradeMap = { A: 0.95, B: 0.78, C: 0.6, D: 0.44, E: 0.28, F: 0.12 };
        ["B", "C", "D", "E", "F"].forEach(function (g) { var upper = "ABCDEF"["ABCDEF".indexOf(g) - 1]; gradeMap[g + "+"] = (gradeMap[g] + gradeMap[upper]) / 2; });

        var axes = [
          { key: "attack", name: "攻击力" },
          { key: "defense", name: "防御力" },
          { key: "magic", name: "魔力量" },
          { key: "control", name: "魔力控制" },
          { key: "physical", name: "体能" },
          { key: "luck", name: "运气" },
        ];

        function polar(r, idx) {
          var angle = (Math.PI * 2 * idx) / 6 - Math.PI / 2;
          return [cx + r * Math.cos(angle), cy + r * Math.sin(angle)];
        }

        function svgEl(tag, attrs) {
          var el = document.createElementNS("http://www.w3.org/2000/svg", tag);
          for (var k in attrs) el.setAttribute(k, attrs[k]);
          return el;
        }

        // 1. 外框大六边形轮廓线
        var outerPts = axes
          .map(function (_, i) {
            return polar(R_outer, i).join(",");
          })
          .join(" ");
        svg.appendChild(
          svgEl("polygon", {
            points: outerPts,
            fill: "none",
            stroke: "#262220",
            "stroke-width": 2.5,
          }),
        );

        // 2. 内部同心正六边形网格
        [0.25, 0.5, 0.75].forEach(function (ratio) {
          var gridPts = axes
            .map(function (_, i) {
              return polar(R_outer * ratio, i).join(",");
            })
            .join(" ");
          svg.appendChild(
            svgEl("polygon", {
              points: gridPts,
              fill: "none",
              stroke: "#3d352e",
              "stroke-width": 1.2,
              opacity: 0.65,
            }),
          );
        });

        // 3. 中心放射径向轴线
        axes.forEach(function (_, i) {
          var end = polar(R_outer, i);
          svg.appendChild(
            svgEl("line", {
              x1: cx,
              y1: cy,
              x2: end[0],
              y2: end[1],
              stroke: "#3d352e",
              "stroke-width": 1.2,
              opacity: 0.7,
            }),
          );
        });

        // 4. 橙红色半透明数据填充多边形
        var hasData = axes.some(function (ax) {
          return !!grades[ax.key];
        });
        if (hasData) {
          var polyPoints = axes
            .map(function (ax, i) {
              var g = grades[ax.key];
              var ratio = g && gradeMap[g] ? gradeMap[g] : 0.1;
              return polar(R_outer * ratio, i).join(",");
            })
            .join(" ");

          svg.appendChild(
            svgEl("polygon", {
              points: polyPoints,
              fill: "rgba(235, 94, 23, 0.82)",
              stroke: "#262220",
              "stroke-width": 1.8,
              "stroke-linejoin": "round",
            }),
          );
        }

        // 5. 六个轴顶端的【黑色正六边形印章徽章】
        var hex_r = 25.5;
        axes.forEach(function (ax, i) {
          var bp = polar(R_outer, i);
          var bx = bp[0],
            by = bp[1];

          // 尖角朝上/朝下的正六边形顶点
          var b_pts = [];
          for (var j = 0; j < 6; j++) {
            var ha = (Math.PI / 3) * j - Math.PI / 2;
            b_pts.push(
              (bx + hex_r * Math.cos(ha)).toFixed(1) +
                "," +
                (by + hex_r * Math.sin(ha)).toFixed(1),
            );
          }

          var badgeGroup = svgEl("g", { class: "radar-badge" });

          // 徽章黑色正六边形本体
          badgeGroup.appendChild(
            svgEl("polygon", {
              points: b_pts.join(" "),
              fill: "#262220",
              stroke: "#161413",
              "stroke-width": 1.6,
            }),
          );

          // 等级大字：白色无衬线超粗体
          var gradeVal = grades[ax.key] || "—";
