          if (/[~/]/.test(name) || ["__proto__", "prototype", "constructor"].includes(name)) throw new Error(location + "名称不能包含 /、~ 或保留键。");
          if (Object.prototype.hasOwnProperty.call(entries, name)) throw new Error(location + "名称“" + name + "”重复，请合并说明或区分名称。");
