        // 8 组明信片自然散落预设：均布于页面中轴与双侧 (5% ~ 92.5%)
        // 核心原理：卡片置于底层 (z-index: 10)，中轴正文卡片与顶部Logo护盾 (z-index: 50~55) 具有 100% 实色羊皮纸底板
        // 卡片穿行文字区时被天然遮挡隐藏，穿出文字区（底部/空隙/侧边）时自然露出！
        var presets = [
          { left: 5.5, duration: 23, delay: -3, tilt: -11, scale: 0.95 },
